CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS collections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), handle text UNIQUE NOT NULL, title text NOT NULL, summary text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published','archived')), position int NOT NULL DEFAULT 0, seo jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), handle text UNIQUE NOT NULL, title text NOT NULL, subtitle text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), price_kobo bigint NOT NULL DEFAULT 0 CHECK(price_kobo>=0), compare_at_kobo bigint CHECK(compare_at_kobo IS NULL OR compare_at_kobo>=0), sku text UNIQUE, stock int NOT NULL DEFAULT 0 CHECK(stock>=0), attributes jsonb NOT NULL DEFAULT '{}', tags jsonb NOT NULL DEFAULT '[]', featured boolean NOT NULL DEFAULT false, seo jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_collections (product_id uuid REFERENCES products(id) ON DELETE CASCADE, collection_id uuid REFERENCES collections(id) ON DELETE CASCADE, position int NOT NULL DEFAULT 0, PRIMARY KEY(product_id,collection_id));
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, phone text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, subject_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('customer','admin')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS staff (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, role text NOT NULL DEFAULT 'owner', status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS carts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid REFERENCES customers(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cart_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cart_id uuid REFERENCES carts(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id), quantity int NOT NULL CHECK(quantity>0), UNIQUE(cart_id,product_id));
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number text UNIQUE NOT NULL, email text NOT NULL, customer_id uuid REFERENCES customers(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'pending', payment_status text NOT NULL DEFAULT 'pending', subtotal_kobo bigint NOT NULL, shipping_kobo bigint NOT NULL DEFAULT 0, total_kobo bigint NOT NULL, access_token_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid REFERENCES orders(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id), title text NOT NULL, quantity int NOT NULL, unit_price_kobo bigint NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys (key text PRIMARY KEY, order_id uuid REFERENCES orders(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, name text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'new', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS newsletter_subscribers (email text PRIMARY KEY, consented_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid REFERENCES products(id) ON DELETE CASCADE, author text NOT NULL, email text NOT NULL, rating int NOT NULL CHECK(rating BETWEEN 1 AND 5), title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
